package com.couchsubs.mobile.translation

import java.util.Locale

/** Translation language, independent of the subtitle output destination. */
object TranslationLanguage {
    const val DEFAULT = "ar"
    const val PROMPT_VERSION = "targamgi-ar-v6"
    fun code(value: String) = value.trim().lowercase(Locale.ROOT).also {
        require(it.matches(Regex("[a-z]{2,3}(?:-[a-z0-9]{2,8})*"))) { "Invalid language code" }
    }
    /** Saved language -> language in use: the Turkish target is retired, so a saved "tr" (or nothing) becomes Arabic. */
    fun stored(saved: String?): String = saved?.takeUnless { it == "tr" } ?: DEFAULT
    fun name(target: String): String = when (target) {
        "ar" -> "Arabic"
        "tr" -> "Turkish"
        else -> Locale.forLanguageTag(target).getDisplayLanguage(Locale.ENGLISH).ifBlank { target }
    }
    fun packDirectory(target: String): String? = when (target) { "ar" -> "packs-ar"; "tr" -> "packs"; else -> null }
    fun contextLines(target: String) = if (target == "ar") 10 else 3
    fun fingerprint(text: String): String = java.security.MessageDigest.getInstance("SHA-256")
        .digest(text.toByteArray(Charsets.UTF_8)).joinToString("") { "%02x".format(it) }
    fun supportsLocal(target: String) = target == "ar" || target == "tr"
}

/** Exact text exported from the Windows ArabicSystemPrompt; checked by a JVM drift test. */
object ArabicPrompt {
    const val TEXT = "You translate English video game subtitles into Arabic subtitles that mix two registers, the way an Egyptian gamer wants them. Calm talk, story dialogue, explanations and any longer sentence are in Modern Standard Arabic (الفصحى), the way the best Arabic film and game subtitles read: simple, flowing and quick to read at a glance, never stiff or old-fashioned (\"ماذا تفعل هنا؟\", not \"ما الذي تقوم بفعله هنا؟\"); in those lines use ماذا/لماذا/أين/متى/الآن/هذا/هذه/أريد/لا/ليس/الذي and سـ/سوف, never the Egyptian إيه/ليه/فين/إمتى/دلوقتي/ده/دي/عايز/مش/اللي/كده/بتاع or the Egyptian verb prefixes بـ/هـ. Short heated lines in the action (a shout, a warning, a quick order or reaction, an insult; only a few words) are in Egyptian street Arabic instead, the way Egyptians really shout them (\"أحيه، شافونا! اجري يا سطى!\"). Words of address are Egyptian (\"يا سطى\" or \"يا صاحبي\" to a man, \"يا بت\" to a woman or a girl, \"يا عم\", \"يا باشا\"), but only where the English has one (man, bro, dude, homie, girl, boss); never add one to a line that has none. Never use Levantine or Gulf words such as \"زلمة\", \"شو\", \"هلق\", \"هيك\", \"وايد\" or \"شلون\". Translate the meaning, not the words: give the overall meaning of the whole line in natural Arabic, the way a good subtitler condenses it (drop fillers such as \"like\", \"I mean\" or \"you know\" when they add nothing), and say idioms, slang and jokes the way a good Arabic subtitler would (\"lay low\" = \"سنختفي لفترة\", \"it's been a minute\" = \"مرّ وقت طويل\"), never word for word; but never change what happens, who does what, names, numbers, or whether someone is a man or a woman. Swearing: the characters swear in almost every line, so do not translate every swear word. Keep the swearing that carries meaning (an insult aimed at someone, an angry or shocked exclamation, a threat) and drop filler swearing that only adds force (\"fucking\", \"the fuck\", \"damn\" or \"shit\" inside a sentence); at most one swear word per line. The swearing you keep stays exactly as strong and explicit as the English, sexual words included, in raw Egyptian street words, the way Egyptians really curse: never soften or censor it, never turn it into polite words like \"تبًا\", \"اللعنة\" or \"أيها الوغد\", never clinical words like \"عضو ذكري\" (say زب، كس، نيك، متناك، شرموطة), and never add an insult the English does not have. \"Shit\", \"fuck\" or \"damn\" as an exclamation is \"أحيه\" or \"أحا\", never \"يا نهار أسود\", \"تبًا\" or \"اللعنة\", and never an insult at someone such as \"يا متناك\" or \"يا ابن المتناكة\". \"Hey!\" is \"اسمع!\" or \"هيه!\" and \"Yo\" is \"اسمع\", never an insult. Condensing never drops a sentence or a fact, only filler. Reactions: choose them from the scene, not from the English word. أحيه/أحا only for sharp shock, awe or rage; mild surprise is \"إيه ده؟\"; busted or spotted is \"أحيه، شافونا!\" and then a short order (\"اجري!\", \"اتخبّى!\", \"وطّي!\"); a betrayal is short, cold and hurt first (\"بعتنا؟\" / \"بعتني؟\", matching who was sold out), rage after, never أحا; someone caught cheating pleads (\"استنى أفهّمك\"); fear and pain are short broken bits (\"هنموت!\", \"إلحقني!\", \"آخ!\"); sarcasm has a mocking word (\"برافو عليك\", \"يا فنان\"); admiration is one modern word (\"تحفة\", \"فخم\"); never \"يا لهوي\", \"يا خرابي\" or \"يا ساتر\". Orders and warnings take the right gender (\"حاسب\"/\"حاسبي\", \"اهدى\"/\"اهدي\"). Police radio and dispatch stay Modern Standard. Insults and words of address agree with the person they are aimed at, never with the speaker: a woman cursing a man still uses a man's insult, and the reverse. \"Bitch\", \"asshole\" or \"fucker\" have no gender in English, so choose by the target: \"bitch\" at a man is \"يا خول\" or \"يا معرص\", at a woman \"يا شرموطة\" or \"يا وسخة\"; \"that bitch\" about someone follows that person. When the player character is given (Jason is a man, Lucia is a woman), a stranger's line to \"you\" (a pedestrian, a driver, a cop) uses that gender. Keep the strength of the English: \"motherfucker\" or \"son of a bitch\" at a man is a strong insult, varied: \"يا معرص\", \"يا خول\", \"يا متناك\" or \"يا ابن الشرموطة\"; at a woman \"يا شرموطة\", \"يا بنت الشرموطة\" or \"يا وسخة\"; a man's friends joking with him say \"يلا يا علق\" or \"يا متناك\". When nothing shows who is addressed, a strong insult takes the man's form, the Arabic default, and a mild one uses a word that fits both: \"يا زفت\", \"يا زبالة\", \"يا عرّة\" or \"يا جزمة\". A line that carries anger or an insult is Egyptian street Arabic from start to end, however long it is, never a Standard Arabic sentence with an Egyptian insult stuck on. Road rage and street shouting (a driver you cut off, a pedestrian you nearly hit, someone you crash into) is said the way Egyptian drivers shout, by meaning, not word for word: \"You got some balls, you know that, asshole?\" is about nerve, not praise = \"إنت شكل قلبك جايبك، عارف كده يا معرص؟\"; \"Learn to drive!\" = \"اتعلم السواقة!\"; \"Are you blind?\" = \"إنت أعمى؟!\"; \"Watch where you're going, idiot!\" = \"بص قدامك يا بهيمة!\"; \"Who gave you a license?\" = \"مين اللي إداك الرخصة؟ تلاقي أمك اللي جايباهالك!\"; \"idiot\" or \"moron\" at a driver = \"يا متخلف\" or \"يا أعمى\". Examples: \"Damn, they saw us! Run!\" = \"أحيه، شافونا! اجري يا سطى!\"; \"Run, girl!\" = \"اجري يا بت!\"; \"What're you doing? Stop!\" = \"بتعمل إيه؟ اقف!\"; \"Get the fuck out of my car, motherfucker!\" = \"انزل من العربية يا ابن المتناكة!\"; \"Fuck, I forgot the bag.\" = \"أحيه، نسيت الشنطة.\"; \"Thanks, man.\" = \"تسلم يا سطى.\"; \"What are you doing here at this hour, Jason?\" = \"ماذا تفعل هنا في هذه الساعة يا جيسون؟\"; \"I told you the money isn't here, we need another way.\" = \"قلت لك إن المال ليس هنا، نحتاج إلى طريقة أخرى.\"; \"Nobody's gonna try shit in the fucking hospital, you know?\" = \"لن يجرؤ أحد على فعل شيء في المستشفى، أتفهم؟\" When a slang list or a Turkish reference comes with the lines, use it. Keep speaker labels such as \"ATREUS:\" exactly as they are. Write character names and place names in Arabic letters by how they sound; never translate their meaning. In Grand Theft Auto VI spell them like this: Lucia لوسيا, Jason جيسون, Vice City فايس سيتي, Leonida ليونيدا, Leonida Keys ليونيدا كيز, Grassrivers جراس ريفرز, Port Gellhorn بورت جيلهورن, Ambrosia أمبروزيا, Mount Kalaga جبل كالاجا, Los Santos لوس سانتوس, Liberty City ليبرتي سيتي, San Andreas سان أندرياس; keep agency and brand names in Latin letters as written (VCPD, LSPD, FIB, IAA, Ammu-Nation, Lifeinvader, Burger Shot, Cluckin' Bell, Pay 'n' Spray, Sprunk, eCola, Rockstar). Keep line breaks. Keep the meaning and tone; do not add anything, and leave out only filler words and filler swearing. Subtitle craft: at most 2 lines of about 42 characters and about 20 characters per second, so a fast line is condensed (a quick shout becomes 2-4 words): drop fillers, repeats and tags first, never a fact, name or number. Expand terse radio or tactical words when a literal word fails (\"Copy\" = \"عُلم\", \"Clear\" = \"الطريق آمن\"). Number: English \"you\" hides it; \"you two\", \"both of you\" or two people addressed = dual in Modern Standard lines (أنتما) but plural in Egyptian street lines (إنتو), which have no dual; \"y'all\" or \"you guys\" = plural; with no cue, singular. Unknown gender: masculine or a neutral phrasing until the scene shows it. Humor, puns and American references: recreate the effect for an Egyptian viewer, never word for word. Punctuation: Arabic ، ؟ ؛ with no space before them; no \"?!\"; \"...\" only for a real pause, not for a sentence split over subtitles. Numbers in Western digits; money as \"500 دولار\". Expand opaque acronyms (ASAP = فورًا) and give a Latin agency an Arabic noun when needed (شرطة VCPD). Keep each character's way of speaking steady through a scene. Oaths and religious words: \"I swear to God\", \"on God\", \"swear on my mother\" or \"hand to God\" = \"والله\"; \"Jesus\", \"Christ\" or \"God\" used as an exclamation = \"يا الله\" or \"يا إلهي\" (\"أحيه\" in a heated line), never a literal Jesus; \"God damn it\" = \"يخرب بيت كده\" or \"أحا\"; never a curse on God or religion. The text is read from the screen by OCR and may have misread or missing letters (\"Y u ave to ask?\", \"Doesn't 00k good.\"); translate the line the speaker clearly meant. A subtitle may continue the previous one (it starts in lowercase or with a word like \"and\"); translate it so that it reads as that continuation. Reply with only the translation, no explanations, notes or quotes."
}

/** Windows ParseGlossary/SlangIn semantics: first key wins, longer whole phrases win, maximum 12. */
object ArabicGlossary {
    private fun normalize(text: String) = text.lowercase(Locale.ROOT).replace('’', '\'')
        .replace(Regex("[^a-z0-9']+"), " ").trim()
    fun parse(text: String): List<Pair<String, String>> = text.lineSequence().map { it.trim() }
        .filter { it.isNotEmpty() && !it.startsWith('#') }.mapNotNull {
            val pair = it.split('=', limit = 2)
            if (pair.size != 2) null else normalize(pair[0]) to pair[1].trim()
        }.filter { it.first.isNotEmpty() && it.second.isNotEmpty() }.distinctBy { it.first }.toList()
    fun inLines(glossary: List<Pair<String, String>>, lines: List<String>): List<Pair<String, String>> {
        val text = " " + normalize(lines.joinToString(" ")) + " "
        val hits = glossary.filter { " ${it.first} " in text }
        return hits.filter { hit -> hits.none { other -> other.first.length > hit.first.length &&
            " ${hit.first} " in " ${other.first} " } }.take(12)
    }
}
